def timemap_ops(ops):
    import bisect
    store = {}
    out = []
    for op in ops:
        if op[0] == 'set':
            _, k, v, t = op
            store.setdefault(k, []).append((t, v))
        else:
            _, k, t = op
            arr = store.get(k, [])
            i = bisect.bisect_right(arr, (t, chr(0x10ffff)))
            out.append(arr[i - 1][1] if i else '')
    return out
